// Localized units. Metric (g/kg/ml/l) is universal; word-units carry a
// singular/plural form per language. The English form stays parser-friendly.
const U = {
  g:  { all:'g' }, kg: { all:'kg' }, ml: { all:'ml' }, l: { all:'l' },
  tbsp: { en:{s:'tbsp',p:'tbsp'}, ro:{s:'lingură',p:'linguri'}, es:{s:'cucharada',p:'cucharadas'}, fr:{s:'c. à s.',p:'c. à s.'}, de:{s:'EL',p:'EL'}, pt:{s:'colher de sopa',p:'colheres de sopa'}, ru:{s:'ст. л.',p:'ст. л.'}, ar:{s:'ملعقة كبيرة',p:'ملاعق كبيرة'}, zh:{s:'大勺',p:'大勺'}, ja:{s:'大さじ',p:'大さじ'}, hi:{s:'बड़ा चम्मच',p:'बड़े चम्मच'}, tr:{s:'yemek kaşığı',p:'yemek kaşığı'}, it:{s:'cucchiaio',p:'cucchiai'}, ko:{s:'큰술',p:'큰술'} },
  tsp:  { en:{s:'tsp',p:'tsp'}, ro:{s:'linguriță',p:'lingurițe'}, es:{s:'cucharadita',p:'cucharaditas'}, fr:{s:'c. à c.',p:'c. à c.'}, de:{s:'TL',p:'TL'}, pt:{s:'colher de chá',p:'colheres de chá'}, ru:{s:'ч. л.',p:'ч. л.'}, ar:{s:'ملعقة صغيرة',p:'ملاعق صغيرة'}, zh:{s:'小勺',p:'小勺'}, ja:{s:'小さじ',p:'小さじ'}, hi:{s:'छोटा चम्मच',p:'छोटे चम्मच'}, tr:{s:'çay kaşığı',p:'çay kaşığı'}, it:{s:'cucchiaino',p:'cucchiaini'}, ko:{s:'작은술',p:'작은술'} },
  clove:{ en:{s:'clove',p:'cloves'}, ro:{s:'cățel',p:'căței'}, es:{s:'diente',p:'dientes'}, fr:{s:'gousse',p:'gousses'}, de:{s:'Zehe',p:'Zehen'}, pt:{s:'dente',p:'dentes'}, ru:{s:'зубчик',p:'зубчика'}, ar:{s:'فص',p:'فصوص'}, zh:{s:'瓣',p:'瓣'}, ja:{s:'片',p:'片'}, hi:{s:'कली',p:'कलियाँ'}, tr:{s:'diş',p:'diş'}, it:{s:'spicchio',p:'spicchi'}, ko:{s:'쪽',p:'쪽'} },
};
function unitStr(key, qty, lang) {
  const u = U[key];
  if (!u) return '';
  if (u.all) return u.all;
  const f = u[lang] || u.en;
  return qty === 1 ? f.s : f.p;
}

