// Assemble the app-facing schema; English ingredient lines stay parser-ready,
// other languages get localized unit words.
function mk(s) {
  const ingredients = {};
  LANGS.forEach(l => {
    ingredients[l] = s.ing.map(it => {
      const qty = it.q != null ? String(it.q) : '';
      const unit = it.u ? unitStr(it.u, it.q, l) : '';
      return [qty, unit, it.n[l] || it.n.en].filter(Boolean).join(' ');
    });
  });
  return {
    id: s.id, name: s.name, origin: s.o, category: CAT,
    servings: s.servings, time: { prepMin: s.prep, cookMin: s.cook },
    costRon: s.costRon, nutrition: s.nut, tags: s.tags,
    ingredients, howIsMade: s.steps,
  };
}

const SPECS = [
  { id:'budget_001', name:NAMES.riceVeg, o:O.INT, servings:2, prep:5, cook:20, costRon:5, nut:{cal:420,prot:9,carb:72,fat:11,fib:6}, tags:['budget','vegan','quick'],
    ing:[ {q:150,u:'g',n:I.rice}, {q:200,u:'g',n:I.frozenVeg}, {q:2,u:'tbsp',n:I.oil}, {q:1,n:I.onion}, {q:2,u:'clove',n:I.garlic}, {n:I.salt} ],
    steps:{
      ro:'Clătește orezul sub apă rece până curge limpede, apoi lasă-l la scurs. Încinge uleiul într-o oală cu fund gros și călește ceapa tocată mărunt și usturoiul 3 minute, până se înmoaie și devin aromate, fără să se rumenească. Adaugă orezul și amestecă un minut, ca fiecare bob să se învelească în ulei și să se prăjească ușor — așa rămâne pufos. Toarnă 300 ml apă, adaugă un praf bun de sare, dă în clocot, apoi redu focul, acoperă și fierbe blând 15 minute, fără să ridici capacul. În ultimele 5 minute presară legumele congelate deasupra, ca să se pătrundă în abur. Stinge focul, ține acoperit încă 2 minute, apoi afânează cu o furculiță și servește.',
      en:'Rinse the rice under cold water until it runs clear, then set it aside to drain. Heat the oil in a heavy pot over medium heat and cook the finely chopped onion and garlic for 3 minutes, until soft and fragrant but not browned. Add the rice and stir for a minute so every grain is coated and lightly toasted — this keeps it fluffy. Pour in 300 ml water, add a good pinch of salt, bring to a boil, then lower the heat, cover, and simmer gently for 15 minutes without lifting the lid. Scatter the frozen vegetables over the top for the last 5 minutes so they steam through. Turn off the heat, leave it covered for 2 more minutes, then fluff with a fork and serve.',
      es:'Enjuaga el arroz bajo agua fría hasta que salga clara y déjalo escurrir. Calienta el aceite en una olla de fondo grueso a fuego medio y sofríe la cebolla picada fina y el ajo 3 minutos, hasta que estén blandos y aromáticos sin dorarse. Añade el arroz y remueve un minuto para que cada grano se cubra de aceite y se tueste ligeramente — así queda suelto. Vierte 300 ml de agua, añade una buena pizca de sal, lleva a ebullición, baja el fuego, tapa y cocina suave 15 minutos sin levantar la tapa. Reparte las verduras congeladas por encima los últimos 5 minutos para que se hagan al vapor. Apaga el fuego, deja tapado 2 minutos más, ahueca con un tenedor y sirve.',
      fr:'Rincez le riz à l’eau froide jusqu’à ce qu’elle soit claire, puis laissez-le égoutter. Chauffez l’huile dans une casserole à fond épais à feu moyen et faites revenir l’oignon finement haché et l’ail 3 minutes, jusqu’à ce qu’ils soient tendres et parfumés sans colorer. Ajoutez le riz et remuez une minute pour enrober et torréfier légèrement chaque grain — c’est ce qui le garde léger. Versez 300 ml d’eau, ajoutez une bonne pincée de sel, portez à ébullition, baissez le feu, couvrez et laissez mijoter doucement 15 minutes sans soulever le couvercle. Répartissez les légumes surgelés sur le dessus les 5 dernières minutes pour qu’ils cuisent à la vapeur. Coupez le feu, laissez couvert 2 minutes de plus, égrenez à la fourchette et servez.',
      de:'Den Reis unter kaltem Wasser abspülen, bis das Wasser klar ist, dann abtropfen lassen. Das Öl in einem schweren Topf bei mittlerer Hitze erhitzen und die fein gehackte Zwiebel mit dem Knoblauch 3 Minuten anschwitzen, bis alles weich und duftend ist, aber ohne Farbe. Den Reis zugeben und eine Minute rühren, damit jedes Korn mit Öl überzogen und leicht angeröstet wird — so bleibt er locker. 300 ml Wasser angießen, eine gute Prise Salz zugeben, aufkochen, dann die Hitze reduzieren, zudecken und 15 Minuten sanft köcheln, ohne den Deckel zu heben. In den letzten 5 Minuten das Tiefkühlgemüse darüber streuen, damit es mitdämpft. Die Hitze abstellen, 2 Minuten zugedeckt ruhen lassen, mit einer Gabel auflockern und servieren.',
      pt:'Lave o arroz em água fria até sair limpa e deixe escorrer. Aqueça o óleo numa panela de fundo grosso em lume médio e refogue a cebola picada fina e o alho 3 minutos, até ficarem macios e aromáticos sem alourar. Junte o arroz e mexa um minuto para envolver e tostar levemente cada grão — é o que o mantém soltinho. Adicione 300 ml de água e uma boa pitada de sal, deixe ferver, baixe o lume, tape e cozinhe brandamente 15 minutos sem levantar a tampa. Espalhe os legumes congelados por cima nos últimos 5 minutos para cozerem no vapor. Desligue o lume, deixe tapado mais 2 minutos, solte com um garfo e sirva.',
      ru:'Промойте рис под холодной водой до прозрачности и дайте стечь. Разогрейте масло в толстостенной кастрюле на среднем огне и обжарьте мелко нарезанные лук и чеснок 3 минуты, до мягкости и аромата, но без румянца. Добавьте рис и помешивайте минуту, чтобы каждое зёрнышко покрылось маслом и слегка обжарилось — так он останется рассыпчатым. Влейте 300 мл воды, добавьте хорошую щепотку соли, доведите до кипения, убавьте огонь, накройте и варите на слабом огне 15 минут, не поднимая крышку. За последние 5 минут выложите сверху замороженные овощи, чтобы они пропарились. Выключите огонь, дайте постоять под крышкой ещё 2 минуты, разрыхлите вилкой и подавайте.',
      ar:'اغسل الأرز تحت الماء البارد حتى يصفو، ثم اتركه ليتصفّى. سخّن الزيت في قدر سميك القاع على نار متوسطة وشوّح البصل المفروم ناعماً والثوم 3 دقائق حتى يلين ويفوح دون أن يحمرّ. أضف الأرز وقلّبه دقيقة حتى تتغطى كل حبة بالزيت وتُحمّص قليلاً — هذا يبقيه مفكّكاً. أضف 300 مل ماء ورشة ملح جيدة، واتركه يغلي، ثم اخفض النار وغطّه واطهه بهدوء 15 دقيقة دون رفع الغطاء. في آخر 5 دقائق وزّع الخضار المجمّدة فوقه لتنضج بالبخار. أطفئ النار واتركه مغطى دقيقتين إضافيتين، ثم فكّكه بشوكة وقدّمه.',
      zh:'米用冷水冲洗至水清，沥干备用。厚底锅中中火热油，下切碎的洋葱和蒜炒3分钟，至变软出香但不上色。加入米翻炒1分钟，让每粒米裹上油并微微焙香——这样米饭才松散。倒入300毫升水，加一大撮盐，煮开后转小火，加盖轻煮15分钟，中途不要揭盖。最后5分钟把冷冻蔬菜铺在上面，用余汽焖熟。关火后加盖再焖2分钟，用叉子拨松即可上桌。',
      ja:'米を冷水で研ぎ、水が澄むまで洗って水を切る。厚手の鍋に油を中火で熱し、みじん切りの玉ねぎとにんにくを3分、色づけないよう柔らかく香りが立つまで炒める。米を加えて1分炒め、全体に油をまとわせて軽く焼き付ける——これでパラッと仕上がる。水300mlと塩ひとつまみをしっかり加えて沸騰させ、弱火にして15分、ふたを開けずに静かに煮る。最後の5分で冷凍野菜を上に散らし、蒸気で火を通す。火を止めてさらに2分蒸らし、フォークでほぐして盛り付ける。',
      hi:'चावल को ठंडे पानी में तब तक धोएँ जब तक पानी साफ न आए, फिर छानकर रख दें। मोटे तले वाले बर्तन में मध्यम आँच पर तेल गरम करें और बारीक कटा प्याज़ व लहसुन 3 मिनट भूनें, जब तक नरम और खुशबूदार न हों पर भूरे न हों। चावल डालकर 1 मिनट चलाएँ ताकि हर दाना तेल में लिपटकर हल्का सिक जाए — इससे चावल खिला-खिला रहता है। 300 मि.ली. पानी और अच्छी चुटकी नमक डालें, उबाल लाएँ, फिर आँच धीमी कर ढककर 15 मिनट बिना ढक्कन उठाए पकाएँ। आख़िरी 5 मिनट में फ्रोज़न सब्ज़ियाँ ऊपर फैलाएँ ताकि भाप में पक जाएँ। आँच बंद कर 2 मिनट और ढका रहने दें, फिर काँटे से खिलाकर परोसें।',
      tr:'Pirinci soğuk suyun altında suyu berraklaşana dek yıkayıp süzülmeye bırakın. Kalın tabanlı tencerede orta ateşte yağı ısıtın, ince doğranmış soğan ve sarımsağı 3 dakika, yumuşayıp kokusu çıkana kadar kızartmadan kavurun. Pirinci ekleyip 1 dakika karıştırın; her tane yağa bulanıp hafifçe kavrulsun — bu onu tane tane tutar. 300 ml su ve iyi bir tutam tuz ekleyip kaynatın, ateşi kısın, kapağını kapatıp 15 dakika kapağı açmadan hafifçe pişirin. Son 5 dakikada dondurulmuş sebzeleri üzerine serpip buharda pişirin. Ocağı kapatın, 2 dakika daha demlendirin, çatalla kabartıp servis edin.',
      it:'Sciacqua il riso sotto acqua fredda finché esce limpida, poi lascialo scolare. Scalda l’olio in una pentola dal fondo spesso a fuoco medio e fai appassire la cipolla tritata fine e l’aglio per 3 minuti, morbidi e profumati ma senza colore. Unisci il riso e mescola un minuto perché ogni chicco si unga e si tosti appena — così resta sgranato. Versa 300 ml d’acqua e una buona presa di sale, porta a bollore, abbassa la fiamma, copri e cuoci dolcemente 15 minuti senza sollevare il coperchio. Distribuisci le verdure surgelate in superficie negli ultimi 5 minuti perché cuociano al vapore. Spegni, lascia coperto altri 2 minuti, sgrana con una forchetta e servi.',
      ko:'쌀을 찬물에 물이 맑아질 때까지 씻어 물기를 뺀다. 두꺼운 냄비에 중불로 기름을 달구고 곱게 다진 양파와 마늘을 3분간, 색이 나지 않게 부드럽고 향이 날 때까지 볶는다. 쌀을 넣고 1분간 볶아 알알이 기름을 입히고 살짝 볶아준다 — 이렇게 하면 밥이 고슬해진다. 물 300ml와 소금 넉넉히 한 꼬집을 넣고 끓인 뒤 불을 줄이고 뚜껑을 덮어 15분간 뚜껑을 열지 않고 약하게 익힌다. 마지막 5분에 냉동 채소를 위에 올려 증기로 익힌다. 불을 끄고 2분 더 뜸을 들인 뒤 포크로 살살 풀어 낸다.' } },

  { id:'budget_002', name:NAMES.pasta, o:O.IT, servings:2, prep:5, cook:15, costRon:4, nut:{cal:480,prot:15,carb:85,fat:9,fib:6}, tags:['budget','vegetarian','quick'],
    ing:[ {q:180,u:'g',n:I.pasta}, {q:300,u:'g',n:I.passata}, {q:2,u:'tbsp',n:I.oil}, {q:3,u:'clove',n:I.garlic}, {n:I.salt} ],
    steps:{
      ro:'Pune la fiert o oală mare cu apă bine sărată și fierbe pastele până sunt al dente, apoi scurge-le păstrând o cană din apa de fierbere. Cât fierb, încălzește uleiul într-o tigaie largă la foc mic și adaugă usturoiul feliat subțire, lăsându-l să sfârâie 1-2 minute până devine auriu-pal și aromat — nu-l rumeni, că amărăște. Toarnă roșiile pasate, un praf de sare, și fierbe sosul 8 minute, până se îngroașă puțin și pierde gustul crud. Adaugă pastele scurse direct în sos și amestecă un minut pe foc, turnând câte puțin din apa păstrată până sosul îmbracă lucios fiecare fir. Gustă, potrivește sarea și servește imediat, cât e cald.',
      en:'Bring a large pot of well-salted water to the boil and cook the pasta until just al dente, then drain, keeping a cup of the starchy water. While it cooks, warm the oil in a wide pan over low heat and add the thinly sliced garlic, letting it gently sizzle for a minute or two until pale gold and fragrant — don’t let it brown or it turns bitter. Pour in the tomato passata with a pinch of salt and simmer for about 8 minutes, until it thickens slightly and loses its raw edge. Tip the drained pasta straight into the sauce and toss over the heat for a minute, adding a splash of the reserved water until it clings glossily to every strand. Taste, adjust the salt, and serve at once while hot.',
      es:'Pon a hervir una olla grande con agua bien salada y cuece la pasta hasta que esté al dente; escurre reservando una taza del agua. Mientras, calienta el aceite en una sartén amplia a fuego bajo y añade el ajo en láminas finas, dejándolo chisporrotear 1-2 minutos hasta que esté dorado pálido y aromático — no lo dores o amarga. Vierte el tomate triturado con una pizca de sal y cocina unos 8 minutos, hasta que espese un poco y pierda el sabor crudo. Echa la pasta escurrida directamente en la salsa y saltea un minuto, añadiendo un poco del agua reservada hasta que envuelva brillante cada hebra. Prueba, ajusta la sal y sirve enseguida bien caliente.',
      fr:'Portez à ébullition une grande casserole d’eau bien salée et faites cuire les pâtes juste al dente, puis égouttez en gardant une tasse d’eau de cuisson. Pendant ce temps, chauffez l’huile dans une grande poêle à feu doux et ajoutez l’ail émincé, en le laissant grésiller 1 à 2 minutes jusqu’à ce qu’il soit doré pâle et parfumé — sans le colorer, sinon il devient amer. Versez les tomates passées avec une pincée de sel et laissez mijoter environ 8 minutes, jusqu’à léger épaississement. Versez les pâtes égouttées directement dans la sauce et remuez une minute sur le feu, en ajoutant un peu d’eau réservée pour qu’elle enrobe brillamment chaque brin. Goûtez, rectifiez le sel et servez aussitôt bien chaud.',
      de:'Einen großen Topf gut gesalzenes Wasser aufkochen und die Pasta al dente garen, dann abgießen und eine Tasse Kochwasser aufbewahren. Währenddessen das Öl in einer weiten Pfanne bei niedriger Hitze erwärmen und den dünn geschnittenen Knoblauch 1-2 Minuten sanft brutzeln lassen, bis er hellgolden und duftend ist — nicht bräunen, sonst wird er bitter. Passierte Tomaten mit einer Prise Salz zugeben und etwa 8 Minuten köcheln, bis die Soße leicht eindickt und den rohen Geschmack verliert. Die abgetropfte Pasta direkt in die Soße geben und eine Minute schwenken, dabei etwas Kochwasser zugießen, bis sie jeden Strang glänzend umhüllt. Abschmecken, salzen und sofort heiß servieren.',
      pt:'Leve ao lume uma panela grande de água bem salgada e coza a massa até ficar al dente; escorra e guarde uma chávena da água. Enquanto isso, aqueça o óleo numa frigideira larga em lume baixo e junte o alho em lâminas finas, deixando fritar 1-2 minutos até ficar dourado claro e aromático — sem alourar, senão amarga. Deite o tomate passata com uma pitada de sal e cozinhe cerca de 8 minutos, até engrossar ligeiramente e perder o sabor cru. Junte a massa escorrida diretamente ao molho e envolva um minuto no lume, adicionando um pouco da água reservada até cobrir cada fio de forma brilhante. Prove, acerte o sal e sirva de imediato bem quente.',
      ru:'Вскипятите большую кастрюлю хорошо подсолённой воды и отварите макароны до состояния аль денте, затем откиньте, сохранив стакан воды. Пока варится, разогрейте масло в широкой сковороде на слабом огне и добавьте тонко нарезанный чеснок, дав ему пошипеть 1-2 минуты до бледно-золотистого цвета и аромата — не подрумянивайте, иначе будет горчить. Влейте протёртые томаты со щепоткой соли и тушите около 8 минут, пока соус слегка не загустеет и не уйдёт сырой привкус. Выложите откинутые макароны прямо в соус и помешивайте минуту на огне, подливая немного отложенной воды, пока соус глянцево не обволочёт каждую макаронину. Попробуйте, посолите и сразу подавайте горячими.',
      ar:'اغلِ قدراً كبيراً من الماء المملّح جيداً واطهُ المكرونة حتى تصبح ألدنتي، ثم صفّها واحتفظ بكوب من ماء السلق. أثناء ذلك سخّن الزيت في مقلاة واسعة على نار هادئة وأضف الثوم المقطّع رقيقاً، واتركه يفحّ 1-2 دقيقة حتى يصير ذهبياً باهتاً وعطرياً — دون أن يحمرّ وإلا صار مرّاً. أضف الطماطم المهروسة مع رشة ملح واطهها نحو 8 دقائق حتى تثخن قليلاً ويزول طعمها النيء. أضف المكرونة المصفّاة مباشرة إلى الصلصة وقلّبها دقيقة على النار، مع إضافة قليل من ماء السلق حتى تغلّف كل خيط بلمعان. تذوّق، اضبط الملح وقدّمها فوراً ساخنة.',
      zh:'大锅烧开充分加盐的水，把意面煮到弹牙，捞出并留一杯煮面水。煮面时，宽口锅小火热油，下切薄片的蒜，煸1-2分钟至淡金色出香——别煸上色，否则发苦。倒入番茄泥加一撮盐，小火煮约8分钟，至略微浓稠、去掉生味。把沥干的意面直接倒入酱汁，开火翻拌1分钟，其间加少许煮面水，让酱汁油亮地裹住每根面条。尝味，调盐，趁热立即上桌。',
      ja:'大きめの鍋にしっかり塩を入れた湯を沸かし、パスタをアルデンテに茹で、ゆで汁を1カップ取り分けて湯を切る。その間に広めのフライパンに油を弱火で温め、薄切りのにんにくを1〜2分、薄いきつね色で香りが立つまで炒める——焦がすと苦くなるので色づけすぎない。トマトピューレと塩ひとつまみを入れ、約8分、少しとろみがつき生っぽさが抜けるまで煮る。湯を切ったパスタをソースに直接入れて1分あおり、取り分けたゆで汁を少しずつ加えて全体につやよく絡める。味をみて塩を調え、熱いうちにすぐ盛り付ける。',
      hi:'एक बड़े बर्तन में अच्छी तरह नमकीन पानी उबालें और पास्ता को अल-डेंटे तक पकाएँ, फिर एक कप पानी बचाकर छान लें। इस बीच चौड़े पैन में धीमी आँच पर तेल गरम करें और पतले कटे लहसुन को 1-2 मिनट हल्का सुनहरा और खुशबूदार होने तक भूनें — भूरा न करें वरना कड़वा हो जाता है। टमाटर प्यूरी और चुटकी नमक डालें और लगभग 8 मिनट पकाएँ जब तक हल्का गाढ़ा हो और कच्चापन चला जाए। छाने पास्ता को सीधे सॉस में डालें और आँच पर 1 मिनट मिलाएँ, बचा पानी थोड़ा-थोड़ा डालते हुए ताकि सॉस हर लच्छे पर चमकदार लिपट जाए। चखें, नमक ठीक करें और तुरंत गरमागरम परोसें।',
      tr:'Büyük bir tencerede iyice tuzlanmış suyu kaynatın ve makarnayı diri (al dente) haşlayın, bir su bardağı suyunu ayırıp süzün. Bu sırada geniş bir tavada yağı kısık ateşte ısıtın ve ince dilimlenmiş sarımsağı 1-2 dakika, açık altın rengi alıp kokusu çıkana kadar cızırdatın — kızartmayın, yoksa acılaşır. Domates püresini bir tutam tuzla ekleyip yaklaşık 8 dakika, hafif koyulaşıp çiğ tadı gidene dek pişirin. Süzülmüş makarnayı doğrudan sosa alın ve ocakta 1 dakika çevirin; ayırdığınız sudan azar azar ekleyerek her teli parlakça sarmasını sağlayın. Tadına bakın, tuzu ayarlayın ve hemen sıcak servis edin.',
      it:'Porta a bollore una pentola capiente di acqua ben salata e cuoci la pasta al dente, poi scola tenendo da parte una tazza d’acqua. Intanto scalda l’olio in una padella ampia a fuoco basso e unisci l’aglio a fettine sottili, lasciandolo sfrigolare 1-2 minuti finché è dorato chiaro e profumato — senza scurirlo, o diventa amaro. Versa la passata con un pizzico di sale e fai sobbollire circa 8 minuti, finché si addensa un po’ e perde il sapore crudo. Butta la pasta scolata direttamente nel sugo e mantecala un minuto sul fuoco, aggiungendo un po’ d’acqua tenuta da parte finché avvolge lucida ogni pezzo. Assaggia, regola il sale e servi subito ben calda.',
      ko:'큰 냄비에 소금을 충분히 넣은 물을 끓여 파스타를 알덴테로 삶고, 면수 한 컵을 남긴 뒤 물을 뺀다. 삶는 동안 넓은 팬에 약불로 기름을 데우고 얇게 저민 마늘을 1~2분간 연한 황금색이 나고 향이 날 때까지 볶는다 — 색이 진해지면 쓴맛이 나니 태우지 않는다. 토마토 퓌레와 소금 한 꼬집을 넣고 약 8분간 살짝 걸쭉해지고 날 맛이 가실 때까지 끓인다. 물 뺀 파스타를 소스에 바로 넣고 1분간 불에서 버무리며, 남긴 면수를 조금씩 더해 소스가 면에 윤기 있게 입혀지도록 한다. 맛을 보고 소금으로 간해 뜨거울 때 바로 낸다.' } },

  { id:'budget_003', name:NAMES.lentil, o:O.ME, servings:2, prep:10, cook:25, costRon:4, nut:{cal:300,prot:18,carb:45,fat:6,fib:12}, tags:['budget','vegan','healthy'],
    ing:[ {q:150,u:'g',n:I.lentils}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:2,u:'tbsp',n:I.oil}, {q:1,u:'l',n:I.water}, {q:1,u:'tsp',n:I.spices}, {q:2,u:'clove',n:I.garlic}, {n:I.salt} ],
    steps:{
      ro:'Încinge uleiul într-o oală și călește blând ceapa, morcovul și usturoiul tocate circa 5 minute, până se înmoaie și se îndulcesc. Clătește lintea sub apă rece și adaug-o împreună cu condimentele, amestecând 30 de secunde ca să se trezească aromele. Toarnă apa, dă în clocot, apoi redu focul și fierbe circa 20 de minute, până lintea e complet moale și începe să se desfacă. Sărează la sfârșit, după gust — sarea pusă devreme poate ține lintea tare. Pentru o supă mai catifelată, pasează o parte și pune-o înapoi, ca să prindă corp. Servește fierbinte, cu pâine dacă ai.',
      en:'Heat the oil in a pot and gently cook the chopped onion, carrot and garlic for about 5 minutes, until softened and sweet. Rinse the lentils under cold water and add them with the spices, stirring for 30 seconds to wake up the aromas. Pour in the water, bring to a boil, then lower the heat and simmer for about 20 minutes, until the lentils are completely tender and starting to break down. Season with salt at the end, to taste — salting early can keep lentils firm. For a smoother soup, blend part of it and stir it back in for body. Serve hot, with bread if you have some.',
      es:'Calienta el aceite en una olla y sofríe suavemente la cebolla, la zanahoria y el ajo picados unos 5 minutos, hasta que se ablanden y endulcen. Enjuaga las lentejas bajo agua fría y añádelas con las especias, removiendo 30 segundos para despertar los aromas. Vierte el agua, lleva a ebullición, baja el fuego y cocina unos 20 minutos, hasta que estén tiernas y empiecen a deshacerse. Sala al final, al gusto — salar pronto puede dejarlas duras. Para una sopa más suave, tritura una parte y devuélvela para dar cuerpo. Sirve caliente, con pan si tienes.',
      fr:'Chauffez l’huile dans une casserole et faites revenir doucement l’oignon, la carotte et l’ail hachés environ 5 minutes, jusqu’à ce qu’ils soient tendres et sucrés. Rincez les lentilles à l’eau froide et ajoutez-les avec les épices, en remuant 30 secondes pour réveiller les arômes. Versez l’eau, portez à ébullition, baissez le feu et laissez mijoter environ 20 minutes, jusqu’à ce que les lentilles soient bien tendres et commencent à se défaire. Salez en fin de cuisson, à votre goût — saler tôt peut les garder fermes. Pour une soupe plus lisse, mixez-en une partie et remettez-la pour donner du corps. Servez chaud, avec du pain si vous en avez.',
      de:'Das Öl in einem Topf erhitzen und Zwiebel, Karotte und Knoblauch gehackt etwa 5 Minuten sanft anschwitzen, bis sie weich und süßlich sind. Die Linsen kalt abspülen und mit den Gewürzen zugeben, 30 Sekunden rühren, um die Aromen zu wecken. Das Wasser angießen, aufkochen, dann die Hitze reduzieren und etwa 20 Minuten köcheln, bis die Linsen ganz weich sind und zu zerfallen beginnen. Erst am Ende nach Geschmack salzen — frühes Salzen kann Linsen hart halten. Für eine sämigere Suppe einen Teil pürieren und wieder unterrühren. Heiß servieren, mit Brot, falls vorhanden.',
      pt:'Aqueça o óleo numa panela e refogue suavemente a cebola, a cenoura e o alho picados cerca de 5 minutos, até ficarem macios e adocicados. Lave as lentilhas em água fria e junte-as com as especiarias, mexendo 30 segundos para despertar os aromas. Deite a água, deixe ferver, baixe o lume e cozinhe cerca de 20 minutos, até as lentilhas ficarem bem macias e a desfazerem-se. Tempere com sal no fim, a gosto — salgar cedo pode mantê-las firmes. Para uma sopa mais aveludada, triture parte e devolva à panela para dar corpo. Sirva quente, com pão se tiver.',
      ru:'Разогрейте масло в кастрюле и мягко потушите нарезанные лук, морковь и чеснок около 5 минут, до мягкости и сладости. Промойте чечевицу холодной водой и добавьте со специями, помешивая 30 секунд, чтобы раскрыть аромат. Влейте воду, доведите до кипения, убавьте огонь и варите около 20 минут, пока чечевица не станет совсем мягкой и не начнёт развариваться. Солите в конце по вкусу — ранняя соль может оставить чечевицу жёсткой. Для более гладкого супа измельчите часть блендером и верните для густоты. Подавайте горячим, с хлебом, если есть.',
      ar:'سخّن الزيت في قدر وشوّح البصل والجزر والثوم المفروم بهدوء نحو 5 دقائق حتى يلين ويحلو مذاقه. اغسل العدس بالماء البارد وأضفه مع البهارات، وقلّب 30 ثانية لإيقاظ النكهات. أضف الماء واتركه يغلي، ثم اخفض النار واطهه نحو 20 دقيقة حتى ينضج العدس تماماً ويبدأ بالتفكك. ملّحه في النهاية حسب الذوق — فالملح المبكر قد يبقيه قاسياً. لشوربة أنعم، اخفق جزءاً منها وأعده للقدر ليمنحها قواماً. قدّمها ساخنة، مع الخبز إن توفّر.',
      zh:'锅中热油，下切好的洋葱、胡萝卜和蒜小火炒约5分钟，至变软回甜。扁豆用冷水洗净，与香料一起下锅，翻炒30秒激出香味。倒入水煮开，转小火煮约20分钟，至扁豆完全软烂、开始化开。最后按口味加盐——过早加盐会让扁豆发硬。想要更顺滑，可将部分汤打成糊再倒回锅中增稠。趁热食用，有面包更佳。',
      ja:'鍋に油を熱し、みじん切りの玉ねぎ、にんじん、にんにくを約5分、柔らかく甘みが出るまでじっくり炒める。レンズ豆を冷水で洗い、スパイスとともに加えて30秒炒め、香りを引き出す。水を注いで沸騰させ、弱火にして約20分、豆が完全に柔らかくなり崩れ始めるまで煮る。塩は最後に好みで——早く入れると豆が硬いままになりやすい。なめらかにしたければ一部をブレンダーにかけて戻し、とろみを出す。熱いうちに、あればパンを添えて供する。',
      hi:'बर्तन में तेल गरम करें और कटा प्याज़, गाजर व लहसुन को लगभग 5 मिनट धीमी आँच पर भूनें, जब तक नरम और मीठे न हो जाएँ। दाल को ठंडे पानी में धोकर मसालों के साथ डालें और 30 सेकंड चलाएँ ताकि खुशबू खुल जाए। पानी डालें, उबाल लाएँ, फिर आँच धीमी कर लगभग 20 मिनट पकाएँ जब तक दाल पूरी तरह नरम होकर घुलने लगे। नमक अंत में स्वादानुसार डालें — जल्दी नमक डालने से दाल सख्त रह सकती है। ज़्यादा मुलायम सूप के लिए कुछ भाग ब्लेंड कर वापस मिला दें। गरमागरम, हो तो ब्रेड के साथ परोसें।',
      tr:'Tencerede yağı ısıtın ve doğranmış soğan, havuç ve sarımsağı yaklaşık 5 dakika, yumuşayıp tatlanana kadar hafifçe kavurun. Mercimeği soğuk suda yıkayıp baharatla birlikte ekleyin ve aromalar açılsın diye 30 saniye karıştırın. Suyu ekleyip kaynatın, ateşi kısıp yaklaşık 20 dakika, mercimek iyice yumuşayıp dağılmaya başlayana dek pişirin. Tuzu en sonda damak tadınıza göre atın — erken tuz mercimeği sert tutabilir. Daha kadifemsi bir çorba için bir kısmını blenderdan geçirip tencereye geri katın. Sıcak, varsa ekmekle servis edin.',
      it:'Scalda l’olio in una pentola e fai appassire dolcemente cipolla, carota e aglio tritati per circa 5 minuti, finché sono morbidi e dolci. Sciacqua le lenticchie in acqua fredda e uniscile con le spezie, mescolando 30 secondi per risvegliare gli aromi. Versa l’acqua, porta a bollore, abbassa la fiamma e cuoci circa 20 minuti, finché le lenticchie sono tenerissime e iniziano a sfaldarsi. Sala alla fine, a piacere — salare presto può tenerle sode. Per una zuppa più vellutata frulla una parte e rimettila in pentola per dare corpo. Servi calda, con pane se ce l’hai.',
      ko:'냄비에 기름을 달구고 다진 양파, 당근, 마늘을 약 5분간 부드럽고 단맛이 날 때까지 은근히 볶는다. 렌틸콩을 찬물에 헹궈 향신료와 함께 넣고 30초 볶아 향을 낸다. 물을 붓고 끓인 뒤 불을 줄여 약 20분간 렌틸콩이 완전히 물러 풀어지기 시작할 때까지 끓인다. 소금은 마지막에 기호대로 — 일찍 넣으면 콩이 단단하게 남을 수 있다. 더 부드러운 수프를 원하면 일부를 갈아 다시 넣어 농도를 낸다. 뜨겁게, 있으면 빵과 함께 낸다.' } },

  { id:'budget_004', name:NAMES.potato, o:O.EE, servings:2, prep:5, cook:20, costRon:3, nut:{cal:320,prot:6,carb:55,fat:9,fib:5}, tags:['budget','vegan','one-pot'],
    ing:[ {q:500,u:'g',n:I.potatoes}, {q:3,u:'clove',n:I.garlic}, {q:2,u:'tbsp',n:I.oil}, {q:1,u:'l',n:I.water}, {n:I.salt} ],
    steps:{
      ro:'Curăță cartofii dacă vrei și taie-i cuburi de mărime egală, ca să se fiarbă uniform. Pune-i într-o oală, acoperă cu apă cu sare și fierbe circa 18 minute, până intră ușor cuțitul, apoi scurge-i bine. Cât fierb, zdrobește usturoiul cu un praf de sare până devine pastă, apoi amestecă-l cu uleiul, ca să obții un dressing aromat. Toarnă uleiul de usturoi peste cartofii calzi și scurși și amestecă ușor, ca să-l absoarbă cât încă aburesc. Gustă, mai adaugă puțină sare dacă e nevoie, și servește cald, ca garnitură sau fel principal ușor.',
      en:'Peel the potatoes if you like and cut them into even chunks so they cook at the same rate. Put them in a pot, cover with salted water, and boil for about 18 minutes, until a knife slips in easily, then drain well. While they cook, crush the garlic to a paste with a pinch of salt, then whisk it into the oil to make a punchy dressing. Pour the garlic oil over the hot, drained potatoes and toss gently so they soak it up while still steaming. Taste and add a little more salt if needed, and serve warm, as a side or a light main.',
      es:'Pela las patatas si quieres y córtalas en trozos iguales para que cuezan a la vez. Ponlas en una olla, cubre con agua con sal y hierve unos 18 minutos, hasta que el cuchillo entre con facilidad, y escurre bien. Mientras, machaca el ajo con una pizca de sal hasta hacer una pasta y bátelo con el aceite para un aliño intenso. Vierte el aceite de ajo sobre las patatas calientes y escurridas y mezcla con cuidado para que lo absorban aún humeantes. Prueba, añade un poco más de sal si hace falta y sirve caliente, como guarnición o plato ligero.',
      fr:'Épluchez les pommes de terre si vous voulez et coupez-les en morceaux réguliers pour une cuisson homogène. Mettez-les dans une casserole, couvrez d’eau salée et faites bouillir environ 18 minutes, jusqu’à ce qu’un couteau s’enfonce facilement, puis égouttez bien. Pendant ce temps, écrasez l’ail en pâte avec une pincée de sel, puis fouettez-le avec l’huile pour une sauce relevée. Versez l’huile à l’ail sur les pommes de terre chaudes et égouttées et mélangez délicatement pour qu’elles l’absorbent encore fumantes. Goûtez, salez un peu plus si besoin, et servez chaud, en accompagnement ou plat léger.',
      de:'Die Kartoffeln nach Belieben schälen und in gleich große Stücke schneiden, damit sie gleichmäßig garen. In einen Topf geben, mit Salzwasser bedecken und etwa 18 Minuten kochen, bis ein Messer leicht hineingleitet, dann gut abgießen. Währenddessen den Knoblauch mit einer Prise Salz zu einer Paste zerdrücken und mit dem Öl zu einem kräftigen Dressing verrühren. Das Knoblauchöl über die heißen, abgetropften Kartoffeln geben und vorsichtig schwenken, damit sie es dampfend aufsaugen. Abschmecken, bei Bedarf etwas nachsalzen und warm servieren, als Beilage oder leichtes Hauptgericht.',
      pt:'Descasque as batatas se quiser e corte-as em pedaços iguais para cozerem por igual. Coloque numa panela, cubra com água com sal e ferva cerca de 18 minutos, até a faca entrar facilmente, e escorra bem. Enquanto cozem, esmague o alho em pasta com uma pitada de sal e misture com o óleo para um tempero intenso. Regue as batatas quentes e escorridas com o azeite de alho e envolva com cuidado para o absorverem ainda a fumegar. Prove, junte mais um pouco de sal se precisar e sirva quente, como acompanhamento ou prato leve.',
      ru:'При желании очистите картофель и нарежьте одинаковыми кусками, чтобы он сварился равномерно. Положите в кастрюлю, залейте подсолённой водой и варите около 18 минут, пока нож не будет легко входить, затем хорошо слейте. Пока варится, разотрите чеснок с щепоткой соли в пасту и смешайте с маслом до яркой заправки. Полейте горячий отваренный картофель чесночным маслом и аккуратно перемешайте, чтобы он впитал его ещё горячим. Попробуйте, при необходимости досолите и подавайте тёплым, как гарнир или лёгкое основное.',
      ar:'قشّر البطاطس إن أردت وقطّعها مكعبات متساوية لتنضج بالتساوي. ضعها في قدر وغطّها بماء مملّح واسلقها نحو 18 دقيقة حتى يدخل السكين بسهولة، ثم صفّها جيداً. أثناء ذلك اهرس الثوم مع رشة ملح حتى يصير عجينة، ثم اخلطه بالزيت لتتبيلة نفّاذة. اسكب زيت الثوم على البطاطس الساخنة المصفّاة وقلّبها برفق لتمتصه وهي لا تزال تفوح بخاراً. تذوّق، أضف قليلاً من الملح إذا لزم، وقدّمها دافئة كطبق جانبي أو رئيسي خفيف.',
      zh:'喜欢的话去皮，把土豆切成大小均匀的块，方便同时熟透。放入锅中，加盐水没过，煮约18分钟，至刀能轻松插入，然后沥干。煮的同时，把蒜加少许盐捣成泥，与油拌匀，做成味浓的酱汁。将蒜油浇在沥干的热土豆上，趁热轻轻翻拌，让它吸收。尝味，需要就再加点盐，趁热作为配菜或清爽主食上桌。',
      ja:'好みでじゃがいもの皮をむき、均一な大きさに切って火通りをそろえる。鍋に入れて塩水をかぶるまで注ぎ、約18分、ナイフがすっと入るまで茹でてしっかり水を切る。茹でる間ににんにくを塩ひとつまみでつぶしてペーストにし、油と混ぜて力強いドレッシングを作る。水を切った熱いじゃがいもにガーリックオイルをかけ、湯気の立つうちにやさしく和えて吸わせる。味をみて必要なら塩を足し、付け合わせや軽い主菜として温かいうちに供する。',
      hi:'चाहें तो आलू छीलें और एक जैसे टुकड़ों में काटें ताकि समान रूप से पकें। बर्तन में डालकर नमकीन पानी से ढकें और लगभग 18 मिनट उबालें, जब तक चाकू आसानी से घुसे, फिर अच्छे से छान लें। इस बीच लहसुन को चुटकी नमक के साथ कूटकर पेस्ट बनाएँ और तेल में मिलाकर तेज़ ड्रेसिंग तैयार करें। गरम, छाने आलू पर लहसुन का तेल डालें और भाप निकलते हुए हल्के हाथ से मिलाएँ ताकि सोख लें। चखें, ज़रूरत हो तो थोड़ा और नमक डालें और गरम, साइड या हल्के मुख्य व्यंजन के रूप में परोसें।',
      tr:'İsterseniz patatesleri soyun ve eşit büyüklükte doğrayın ki aynı anda pişsin. Tencereye alıp tuzlu suyla örtün ve bıçak kolayca girene kadar yaklaşık 18 dakika haşlayıp iyice süzün. Bu sırada sarımsağı bir tutam tuzla ezerek macun yapın ve yağla çırparak dolgun bir sos hazırlayın. Sarımsaklı yağı sıcak, süzülmüş patateslerin üzerine gezdirin ve buğusu tüterken nazikçe karıştırıp emmesini sağlayın. Tadına bakın, gerekirse biraz tuz ekleyin ve ılık, garnitür ya da hafif ana yemek olarak servis edin.',
      it:'Se vuoi sbuccia le patate e tagliale a pezzi regolari così cuociono in modo uniforme. Mettile in pentola, coprile con acqua salata e lessale circa 18 minuti, finché un coltello entra facilmente, poi scola bene. Mentre cuociono, schiaccia l’aglio a crema con un pizzico di sale e mescolalo con l’olio per un condimento deciso. Versa l’olio all’aglio sulle patate calde e scolate e mescola delicatamente perché lo assorbano ancora fumanti. Assaggia, aggiungi altro sale se serve e servi calde, come contorno o piatto leggero.',
      ko:'원하면 감자 껍질을 벗기고 고르게 익도록 같은 크기로 썬다. 냄비에 담아 소금물을 잠기게 붓고 칼이 쑥 들어갈 때까지 약 18분간 삶은 뒤 물기를 잘 뺀다. 삶는 동안 마늘을 소금 한 꼬집과 함께 으깨 페이스트로 만들고 기름과 섞어 진한 드레싱을 만든다. 물 뺀 뜨거운 감자에 마늘 기름을 붓고 김이 오르는 동안 살살 버무려 배어들게 한다. 맛을 보고 필요하면 소금을 조금 더 넣어, 곁들임이나 가벼운 메인으로 따뜻하게 낸다.' } },

  { id:'budget_005', name:NAMES.beans, o:O.INT, servings:2, prep:5, cook:15, costRon:4, nut:{cal:350,prot:17,carb:50,fat:8,fib:14}, tags:['budget','vegan','high-protein'],
    ing:[ {q:400,u:'g',n:I.beans}, {q:1,n:I.onion}, {q:2,u:'tbsp',n:I.oil}, {q:150,u:'g',n:I.passata}, {q:2,u:'clove',n:I.garlic}, {q:1,u:'tsp',n:I.spices}, {n:I.salt} ],
    steps:{
      ro:'Încălzește uleiul într-o tigaie și călește ceapa și usturoiul tocate la foc mediu circa 5 minute, până se înmoaie și se rumenesc ușor. Adaugă roșiile pasate și condimentele și lasă-le 3 minute, ca sosul să prindă profunzime. Scurge și clătește fasolea, adaug-o în tigaie și fierbe blând 8 minute. Zdrobește o lingură de fasole pe peretele tigăii și amestec-o înapoi — asta îngroașă sosul și îl face cremos. Potrivește de sare și, dacă se usucă prea tare, adaugă un strop de apă. Servește cald.',
      en:'Warm the oil in a pan and cook the chopped onion and garlic over medium heat for about 5 minutes, until soft and lightly golden. Stir in the tomato passata and spices and let them cook for 3 minutes so the sauce deepens. Drain and rinse the beans, add them to the pan, and simmer gently for 8 minutes. Mash a spoonful of the beans against the side of the pan and stir it back in — this thickens the sauce and makes it creamy. Season with salt, and add a splash of water if it gets too dry. Serve warm.',
      es:'Calienta el aceite en una sartén y sofríe la cebolla y el ajo picados a fuego medio unos 5 minutos, hasta que estén blandos y dorados. Añade el tomate triturado y las especias y cocina 3 minutos para que la salsa gane profundidad. Escurre y enjuaga los frijoles, añádelos y cocina suave 8 minutos. Aplasta una cucharada de frijoles contra la sartén y remueve — así espesa la salsa y queda cremosa. Sazona con sal y añade un chorrito de agua si se seca demasiado. Sirve caliente.',
      fr:'Chauffez l’huile dans une poêle et faites revenir l’oignon et l’ail hachés à feu moyen environ 5 minutes, jusqu’à ce qu’ils soient tendres et dorés. Ajoutez les tomates passées et les épices et laissez cuire 3 minutes pour que la sauce gagne en profondeur. Égouttez et rincez les haricots, ajoutez-les et laissez mijoter doucement 8 minutes. Écrasez une cuillerée de haricots contre la poêle et remuez — cela épaissit la sauce et la rend crémeuse. Salez et ajoutez un peu d’eau si cela sèche trop. Servez chaud.',
      de:'Das Öl in einer Pfanne erwärmen und Zwiebel und Knoblauch gehackt bei mittlerer Hitze etwa 5 Minuten braten, bis sie weich und leicht goldbraun sind. Passierte Tomaten und Gewürze einrühren und 3 Minuten kochen, damit die Soße Tiefe bekommt. Die Bohnen abtropfen und abspülen, zugeben und 8 Minuten sanft köcheln. Einen Löffel Bohnen am Pfannenrand zerdrücken und wieder unterrühren — das bindet die Soße und macht sie cremig. Mit Salz abschmecken und bei Bedarf einen Schuss Wasser zugeben. Warm servieren.',
      pt:'Aqueça o óleo numa frigideira e refogue a cebola e o alho picados em lume médio cerca de 5 minutos, até ficarem macios e dourados. Junte o tomate passata e as especiarias e deixe cozer 3 minutos para o molho ganhar profundidade. Escorra e lave o feijão, junte-o e cozinhe brandamente 8 minutos. Esmague uma colher de feijão contra a frigideira e envolva — isto engrossa o molho e deixa-o cremoso. Tempere com sal e junte um pouco de água se secar demais. Sirva quente.',
      ru:'Разогрейте масло на сковороде и обжарьте нарезанные лук и чеснок на среднем огне около 5 минут, до мягкости и лёгкой золотистости. Вмешайте протёртые томаты и специи и готовьте 3 минуты, чтобы соус стал глубже по вкусу. Слейте и промойте фасоль, добавьте её и тушите на слабом огне 8 минут. Разомните ложку фасоли о стенку сковороды и вмешайте обратно — так соус загустеет и станет кремовым. Посолите и добавьте немного воды, если станет суховато. Подавайте тёплым.',
      ar:'سخّن الزيت في مقلاة وشوّح البصل والثوم المفروم على نار متوسطة نحو 5 دقائق حتى يلين ويكتسب لوناً ذهبياً خفيفاً. أضف الطماطم المهروسة والبهارات واطهها 3 دقائق ليكتسب المذاق عمقاً. صفّ الفاصوليا واغسلها، أضفها واطهها بهدوء 8 دقائق. اهرس ملعقة من الفاصوليا على جدار المقلاة وأعِد تقليبها — هذا يكثّف الصلصة ويجعلها كريمية. تبّل بالملح، وأضف رشة ماء إن جفّت كثيراً. قدّمها دافئة.',
      zh:'锅中热油，中火下切好的洋葱和蒜炒约5分钟，至变软微黄。加入番茄泥和香料炒3分钟，让酱汁更有层次。豆子沥干冲洗后下锅，小火煮8分钟。用勺把一勺豆子压在锅壁上再拌回去——这样酱汁更浓稠、口感更绵。加盐调味，太干就加一点水。趁热食用。',
      ja:'フライパンに油を温め、みじん切りの玉ねぎとにんにくを中火で約5分、柔らかく薄く色づくまで炒める。トマトピューレとスパイスを加え、3分煮てソースに深みを出す。豆を水切りして洗い、加えて8分ほど静かに煮る。豆を大さじ1杯分だけ鍋肌でつぶして戻すと、ソースにとろみが出て口当たりがよくなる。塩で味を調え、乾きすぎたら水を少し足す。温かいうちに供する。',
      hi:'पैन में तेल गरम करें और कटा प्याज़ व लहसुन मध्यम आँच पर लगभग 5 मिनट भूनें, जब तक नरम और हल्के सुनहरे हों। टमाटर प्यूरी और मसाले डालकर 3 मिनट पकाएँ ताकि सॉस में गहराई आए। बीन्स को छानकर धोएँ, पैन में डालें और 8 मिनट धीमी आँच पर पकाएँ। एक चम्मच बीन्स को पैन की दीवार पर दबाकर मसलें और वापस मिलाएँ — इससे सॉस गाढ़ी और मलाईदार होती है। नमक डालें और ज़्यादा सूखने पर थोड़ा पानी डालें। गरम परोसें।',
      tr:'Tavada yağı ısıtın ve doğranmış soğan ile sarımsağı orta ateşte yaklaşık 5 dakika, yumuşayıp hafif kızarana dek kavurun. Domates püresi ve baharatı ekleyip 3 dakika pişirin ki sos derinleşsin. Fasulyeyi süzüp durulayın, ekleyin ve 8 dakika hafifçe pişirin. Bir kaşık fasulyeyi tava kenarında ezip geri karıştırın — bu sosu koyulaştırıp kremamsı yapar. Tuzla tatlandırın, fazla kuruyorsa biraz su ekleyin. Ilık servis edin.',
      it:'Scalda l’olio in una padella e rosola cipolla e aglio tritati a fuoco medio per circa 5 minuti, finché sono morbidi e dorati. Unisci la passata e le spezie e cuoci 3 minuti perché il sugo prenda profondità. Scola e sciacqua i fagioli, aggiungili e fai sobbollire dolcemente 8 minuti. Schiaccia un cucchiaio di fagioli sul bordo della padella e rimescola — così il sugo si addensa e diventa cremoso. Regola di sale e aggiungi un goccio d’acqua se asciuga troppo. Servi caldo.',
      ko:'팬에 기름을 데우고 다진 양파와 마늘을 중불에서 약 5분간 부드럽고 살짝 노릇해질 때까지 볶는다. 토마토 퓌레와 향신료를 넣고 3분간 볶아 소스에 깊은 맛을 낸다. 콩을 헹궈 물기를 빼고 넣어 8분간 은근히 끓인다. 콩 한 숟갈을 팬 벽에 눌러 으깬 뒤 다시 섞으면 소스가 걸쭉하고 크리미해진다. 소금으로 간하고, 너무 되직하면 물을 조금 넣는다. 따뜻하게 낸다.' } },

  { id:'budget_006', name:NAMES.chickpea, o:O.ME, servings:2, prep:5, cook:15, costRon:4, nut:{cal:380,prot:16,carb:48,fat:12,fib:13}, tags:['budget','vegan','quick'],
    ing:[ {q:400,u:'g',n:I.chickpeas}, {q:1,n:I.onion}, {q:2,u:'tbsp',n:I.oil}, {q:1,u:'tsp',n:I.spices}, {q:2,u:'clove',n:I.garlic}, {q:150,u:'g',n:I.passata}, {n:I.salt} ],
    steps:{
      ro:'Încinge uleiul și călește ceapa și usturoiul tocate circa 4 minute, până se înmoaie. Adaugă condimentele și amestecă 30 de secunde, ca să se prăjească ușor și să-și scoată aroma. Toarnă roșiile pasate și fierbe 3 minute, până se îngroașă. Scurge și clătește năutul, adaug-o și fierbe blând 8 minute, ca să se pătrundă de arome. Potrivește de sare și subțiază cu puțină apă dacă e nevoie. Servește cald, simplu sau cu orez ori pâine.',
      en:'Heat the oil and cook the chopped onion and garlic for about 4 minutes, until soft. Add the spices and stir for 30 seconds to toast them, which brings out their aroma. Pour in the tomato passata and cook for 3 minutes until it thickens. Drain and rinse the chickpeas, tip them in, and simmer for 8 minutes so they soak up the flavour. Season with salt and loosen with a little water if needed. Serve warm, on its own or with rice or bread.',
      es:'Calienta el aceite y sofríe la cebolla y el ajo picados unos 4 minutos, hasta que estén blandos. Añade las especias y remueve 30 segundos para tostarlas y liberar su aroma. Vierte el tomate triturado y cocina 3 minutos hasta que espese. Escurre y enjuaga los garbanzos, incorpóralos y cocina suave 8 minutos para que absorban el sabor. Sazona con sal y afloja con un poco de agua si hace falta. Sirve caliente, solo o con arroz o pan.',
      fr:'Chauffez l’huile et faites revenir l’oignon et l’ail hachés environ 4 minutes, jusqu’à ce qu’ils soient tendres. Ajoutez les épices et remuez 30 secondes pour les torréfier et libérer leur arôme. Versez les tomates passées et faites cuire 3 minutes jusqu’à épaississement. Égouttez et rincez les pois chiches, ajoutez-les et laissez mijoter 8 minutes pour qu’ils s’imprègnent. Salez et détendez avec un peu d’eau si besoin. Servez chaud, seul ou avec du riz ou du pain.',
      de:'Das Öl erhitzen und Zwiebel und Knoblauch gehackt etwa 4 Minuten anschwitzen, bis sie weich sind. Die Gewürze zugeben und 30 Sekunden rühren, um sie anzurösten und das Aroma zu wecken. Passierte Tomaten angießen und 3 Minuten kochen, bis sie eindicken. Die Kichererbsen abtropfen und abspülen, zugeben und 8 Minuten köcheln, damit sie Geschmack aufnehmen. Mit Salz abschmecken und bei Bedarf mit etwas Wasser lockern. Warm servieren, pur oder mit Reis oder Brot.',
      pt:'Aqueça o óleo e refogue a cebola e o alho picados cerca de 4 minutos, até ficarem macios. Junte as especiarias e mexa 30 segundos para tostar e libertar o aroma. Deite o tomate passata e cozinhe 3 minutos até engrossar. Escorra e lave o grão-de-bico, junte-o e cozinhe brandamente 8 minutos para absorver o sabor. Tempere com sal e solte com um pouco de água se precisar. Sirva quente, simples ou com arroz ou pão.',
      ru:'Разогрейте масло и обжарьте нарезанные лук и чеснок около 4 минут, до мягкости. Добавьте специи и помешивайте 30 секунд, слегка обжаривая, чтобы раскрыть аромат. Влейте протёртые томаты и готовьте 3 минуты до загустения. Слейте и промойте нут, добавьте его и тушите 8 минут, чтобы он пропитался вкусом. Посолите и разбавьте небольшим количеством воды при необходимости. Подавайте тёплым, сам по себе или с рисом либо хлебом.',
      ar:'سخّن الزيت وشوّح البصل والثوم المفروم نحو 4 دقائق حتى يلين. أضف البهارات وقلّب 30 ثانية لتحميصها وإبراز نكهتها. أضف الطماطم المهروسة واطهها 3 دقائق حتى تثخن. صفّ الحمص واغسله، أضفه واطهه بهدوء 8 دقائق ليتشرّب النكهة. تبّل بالملح وخفّفه بقليل من الماء إن لزم. قدّمه دافئاً، وحده أو مع الأرز أو الخبز.',
      zh:'热油，下切好的洋葱和蒜炒约4分钟至变软。加入香料翻炒30秒，稍加焙香激出味道。倒入番茄泥炒3分钟至浓稠。鹰嘴豆沥干冲洗后下锅，小火煮8分钟入味。加盐调味，需要就加一点水调稀。趁热食用，可单吃或配米饭、面包。',
      ja:'油を熱し、みじん切りの玉ねぎとにんにくを約4分、柔らかくなるまで炒める。スパイスを加えて30秒炒め、軽く焙って香りを引き出す。トマトピューレを注ぎ、3分煮てとろみをつける。ひよこ豆を水切りして洗い、加えて8分ほど煮て味を含ませる。塩で味を調え、必要なら水を少し足してゆるめる。温かいうちに、そのまま、あるいはご飯やパンと供する。',
      hi:'तेल गरम करें और कटा प्याज़ व लहसुन लगभग 4 मिनट नरम होने तक भूनें। मसाले डालकर 30 सेकंड चलाएँ ताकि हल्के भुनकर खुशबू खुले। टमाटर प्यूरी डालकर 3 मिनट गाढ़ा होने तक पकाएँ। चनों को छानकर धोएँ, डालें और 8 मिनट धीमी आँच पर पकाएँ ताकि स्वाद सोख लें। नमक डालें और ज़रूरत हो तो थोड़ा पानी मिलाएँ। गरम, अकेले या चावल/रोटी के साथ परोसें।',
      tr:'Yağı ısıtın ve doğranmış soğan ile sarımsağı yaklaşık 4 dakika, yumuşayana dek kavurun. Baharatı ekleyip 30 saniye karıştırın; hafifçe kavrulup kokusu açılsın. Domates püresini dökün ve koyulaşana dek 3 dakika pişirin. Nohutu süzüp durulayın, ekleyin ve 8 dakika hafifçe pişirerek tadı çekmesini sağlayın. Tuzla tatlandırın, gerekirse biraz suyla açın. Ilık, tek başına ya da pilav veya ekmekle servis edin.',
      it:'Scalda l’olio e fai appassire cipolla e aglio tritati per circa 4 minuti, finché sono morbidi. Aggiungi le spezie e mescola 30 secondi per tostarle e sprigionare l’aroma. Versa la passata e cuoci 3 minuti finché si addensa. Scola e sciacqua i ceci, uniscili e fai sobbollire 8 minuti perché assorbano il sapore. Regola di sale e allunga con un po’ d’acqua se serve. Servi caldo, da solo o con riso o pane.',
      ko:'기름을 달구고 다진 양파와 마늘을 약 4분간 부드러워질 때까지 볶는다. 향신료를 넣고 30초 볶아 살짝 볶아 향을 낸다. 토마토 퓌레를 붓고 3분간 걸쭉해질 때까지 끓인다. 병아리콩을 헹궈 물기를 빼고 넣어 8분간 은근히 끓여 맛이 배게 한다. 소금으로 간하고 필요하면 물을 조금 넣어 농도를 맞춘다. 따뜻하게, 그대로 또는 밥이나 빵과 함께 낸다.' } },

  { id:'budget_007', name:NAMES.omelet, o:O.FR, servings:2, prep:5, cook:8, costRon:4, nut:{cal:300,prot:20,carb:5,fat:22,fib:1}, tags:['budget','vegetarian','high-protein','quick'],
    ing:[ {q:4,n:I.eggs}, {q:1,u:'tbsp',n:I.oil}, {q:1,n:I.onion}, {q:1,u:'clove',n:I.garlic}, {n:I.salt} ],
    steps:{
      ro:'Sparge ouăle într-un bol, adaugă un praf de sare și bate bine până gălbenușurile și albușurile se unesc complet. Încinge uleiul într-o tigaie antiaderentă la foc mediu și călește ceapa și usturoiul tocate mărunt 2 minute, până devin aromate. Toarnă ouăle și lasă-le câteva secunde, apoi împinge ușor marginile prinse spre centru, ca oul crud să curgă dedesubt. Când suprafața e aproape închegată, dar încă puțin moale, împăturește omleta în două. Las-o câteva secunde să se așeze, apoi scoate-o pe farfurie și servește imediat.',
      en:'Crack the eggs into a bowl, add a pinch of salt, and beat well until the yolks and whites are fully combined. Heat the oil in a non-stick pan over medium heat and soften the finely chopped onion and garlic for 2 minutes, until fragrant. Pour in the eggs and let them sit for a few seconds, then gently push the setting edges towards the centre so the runny egg flows underneath. When the top is just set but still a little soft, fold the omelet in half. Let it settle for a few seconds, then slide it onto a plate and serve straight away.',
      es:'Casca los huevos en un bol, añade una pizca de sal y bate bien hasta que las yemas y claras se integren del todo. Calienta el aceite en una sartén antiadherente a fuego medio y sofríe la cebolla y el ajo bien picados 2 minutos, hasta que estén aromáticos. Vierte los huevos y déjalos unos segundos, luego empuja con cuidado los bordes cuajados hacia el centro para que el huevo líquido corra debajo. Cuando la superficie esté casi cuajada pero aún algo blanda, dobla la tortilla por la mitad. Déjala asentar unos segundos, pásala a un plato y sirve enseguida.',
      fr:'Cassez les œufs dans un bol, ajoutez une pincée de sel et battez bien jusqu’à ce que jaunes et blancs soient parfaitement mêlés. Chauffez l’huile dans une poêle antiadhésive à feu moyen et faites revenir l’oignon et l’ail finement hachés 2 minutes, jusqu’à ce qu’ils embaument. Versez les œufs et laissez quelques secondes, puis ramenez doucement les bords pris vers le centre pour que l’œuf liquide coule dessous. Quand le dessus est juste pris mais encore un peu moelleux, pliez l’omelette en deux. Laissez reposer quelques secondes, faites-la glisser dans une assiette et servez aussitôt.',
      de:'Die Eier in eine Schüssel schlagen, eine Prise Salz zugeben und gut verquirlen, bis Eigelb und Eiweiß vollständig verbunden sind. Das Öl in einer beschichteten Pfanne bei mittlerer Hitze erhitzen und die fein gehackte Zwiebel mit dem Knoblauch 2 Minuten anschwitzen, bis es duftet. Die Eier angießen, ein paar Sekunden stehen lassen, dann die gestockten Ränder sanft zur Mitte schieben, damit das flüssige Ei darunterfließt. Wenn die Oberfläche gerade gestockt, aber noch etwas weich ist, das Omelett zur Hälfte klappen. Kurz ruhen lassen, auf einen Teller gleiten lassen und sofort servieren.',
      pt:'Parta os ovos numa tigela, junte uma pitada de sal e bata bem até as gemas e claras se integrarem. Aqueça o óleo numa frigideira antiaderente em lume médio e refogue a cebola e o alho bem picados 2 minutos, até ficarem aromáticos. Deite os ovos e deixe uns segundos, depois empurre com cuidado as bordas presas para o centro para o ovo líquido correr por baixo. Quando o topo estiver quase preso mas ainda um pouco mole, dobre a omelete ao meio. Deixe assentar uns segundos, deslize para um prato e sirva de imediato.',
      ru:'Разбейте яйца в миску, добавьте щепотку соли и хорошо взбейте, пока желтки и белки полностью не соединятся. Разогрейте масло в антипригарной сковороде на среднем огне и обжарьте мелко нарезанные лук и чеснок 2 минуты, до аромата. Влейте яйца, дайте им схватиться пару секунд, затем аккуратно сдвигайте застывающие края к центру, чтобы жидкое яйцо стекало вниз. Когда верх едва схватится, но ещё будет чуть мягким, сложите омлет пополам. Дайте постоять несколько секунд, переложите на тарелку и сразу подавайте.',
      ar:'اكسر البيض في وعاء، أضف رشة ملح واخفقه جيداً حتى يمتزج الصفار والبياض تماماً. سخّن الزيت في مقلاة غير لاصقة على نار متوسطة وشوّح البصل والثوم المفروم ناعماً دقيقتين حتى تفوح رائحته. اسكب البيض واتركه ثوانٍ، ثم ادفع الأطراف المتماسكة برفق نحو الوسط ليجري البيض السائل تحتها. عندما يتماسك السطح مع بقائه طرياً قليلاً، اطوِ العجة نصفين. اتركها ثوانٍ لتستقر، ثم أخرجها إلى طبق وقدّمها فوراً.',
      zh:'鸡蛋打入碗中，加一撮盐，充分打散至蛋黄蛋清完全融合。不粘锅中火热油，下切碎的洋葱和蒜炒2分钟出香。倒入蛋液，静置几秒，然后轻轻把凝固的边缘往中间推，让未熟蛋液流到下面。表面刚凝固但仍略软时，把蛋卷对折。静置几秒定型，滑入盘中立即上桌。',
      ja:'卵をボウルに割り入れ、塩ひとつまみを加えて黄身と白身が完全に混ざるまでよく溶く。フッ素樹脂加工のフライパンに油を中火で熱し、みじん切りの玉ねぎとにんにくを2分、香りが立つまで炒める。卵液を流し入れて数秒おき、固まってきた縁をやさしく中央へ寄せ、生の卵液を下へ流す。表面がほぼ固まってまだ少し柔らかいうちに、オムレツを半分に折る。数秒落ち着かせてから皿に滑らせ、すぐに供する。',
      hi:'अंडों को कटोरे में फोड़ें, चुटकी नमक डालें और जर्दी-सफेदी पूरी तरह मिलने तक अच्छे से फेंटें। नॉन-स्टिक पैन में मध्यम आँच पर तेल गरम करें और बारीक कटा प्याज़ व लहसुन 2 मिनट खुशबूदार होने तक भूनें। अंडे डालें, कुछ सेकंड रुकें, फिर जमे किनारों को धीरे से बीच की ओर धकेलें ताकि कच्चा अंडा नीचे बह जाए। जब ऊपर की सतह लगभग जम जाए पर थोड़ी नरम रहे, ऑमलेट को आधा मोड़ें। कुछ सेकंड सेट होने दें, प्लेट पर निकालें और तुरंत परोसें।',
      tr:'Yumurtaları bir kaseye kırın, bir tutam tuz ekleyin ve sarısı ile beyazı tamamen birleşene dek iyice çırpın. Yapışmaz tavada orta ateşte yağı ısıtın ve ince doğranmış soğan ile sarımsağı 2 dakika, kokusu çıkana dek kavurun. Yumurtayı dökün, birkaç saniye bekletin, sonra tutmaya başlayan kenarları nazikçe ortaya doğru itin ki akışkan yumurta altına yayılsın. Üst yüzey tam tutmuşken hâlâ biraz yumuşakken omleti ikiye katlayın. Birkaç saniye dinlendirip tabağa alın ve hemen servis edin.',
      it:'Rompi le uova in una ciotola, aggiungi un pizzico di sale e sbatti bene finché tuorli e albumi sono ben amalgamati. Scalda l’olio in una padella antiaderente a fuoco medio e fai appassire cipolla e aglio tritati fini per 2 minuti, finché profumano. Versa le uova, lasciale rapprendere qualche secondo, poi spingi delicatamente i bordi rappresi verso il centro perché l’uovo liquido scorra sotto. Quando la superficie è appena rappresa ma ancora un po’ morbida, piega l’omelette a metà. Lasciala assestare qualche secondo, falla scivolare nel piatto e servi subito.',
      ko:'계란을 볼에 깨 넣고 소금 한 꼬집을 더해 노른자와 흰자가 완전히 섞이도록 잘 푼다. 코팅 팬에 중불로 기름을 달구고 곱게 다진 양파와 마늘을 2분간 향이 날 때까지 볶는다. 계란물을 붓고 몇 초 두었다가 익은 가장자리를 살살 가운데로 밀어 덜 익은 계란이 아래로 흐르게 한다. 윗면이 막 익고 아직 약간 촉촉할 때 오믈렛을 반으로 접는다. 몇 초 안정시킨 뒤 접시에 옮겨 바로 낸다.' } },

  { id:'budget_008', name:NAMES.cabbage, o:O.EE, servings:2, prep:10, cook:25, costRon:3, nut:{cal:220,prot:5,carb:25,fat:12,fib:8}, tags:['budget','vegan','healthy'],
    ing:[ {q:500,u:'g',n:I.cabbage}, {q:1,n:I.onion}, {q:3,u:'tbsp',n:I.oil}, {q:150,u:'g',n:I.passata}, {q:2,u:'clove',n:I.garlic}, {q:1,u:'tsp',n:I.spices}, {n:I.salt} ],
    steps:{
      ro:'Taie varza fâșii subțiri și ceapa felii. Încălzește uleiul într-o tigaie largă și călește ceapa și usturoiul 4 minute, până se înmoaie. Adaugă varza și gătește la foc mediu, amestecând des, circa 8 minute, până se lasă și scade în volum. Adaugă roșiile pasate și condimentele, redu focul și fierbe 10 minute, până varza e fragedă și lucioasă. Potrivește de sare după gust și servește caldă, ca fel principal sau garnitură consistentă.',
      en:'Finely shred the cabbage and thinly slice the onion. Warm the oil in a wide pan and cook the onion and garlic for 4 minutes, until soft. Add the cabbage and cook over medium heat, stirring often, for about 8 minutes until it wilts down and reduces in volume. Stir in the tomato passata and spices, then lower the heat and simmer for 10 minutes, until the cabbage is tender and glazed. Season with salt to taste, and serve warm as a main or a hearty side.',
      es:'Corta el repollo en tiras finas y la cebolla en rodajas. Calienta el aceite en una sartén amplia y sofríe la cebolla y el ajo 4 minutos, hasta que estén blandos. Añade el repollo y cocina a fuego medio, removiendo a menudo, unos 8 minutos hasta que se ablande y reduzca. Agrega el tomate triturado y las especias, baja el fuego y cocina 10 minutos, hasta que el repollo esté tierno y glaseado. Sazona con sal al gusto y sirve caliente, como plato principal o guarnición contundente.',
      fr:'Émincez finement le chou et coupez l’oignon en fines tranches. Chauffez l’huile dans une grande poêle et faites revenir l’oignon et l’ail 4 minutes, jusqu’à ce qu’ils soient tendres. Ajoutez le chou et faites cuire à feu moyen, en remuant souvent, environ 8 minutes jusqu’à ce qu’il tombe et réduise. Ajoutez les tomates passées et les épices, baissez le feu et laissez mijoter 10 minutes, jusqu’à ce que le chou soit tendre et brillant. Salez à votre goût et servez chaud, en plat principal ou accompagnement généreux.',
      de:'Den Kohl fein hobeln und die Zwiebel in dünne Scheiben schneiden. Das Öl in einer weiten Pfanne erwärmen und Zwiebel und Knoblauch 4 Minuten anschwitzen, bis sie weich sind. Den Kohl zugeben und bei mittlerer Hitze unter häufigem Rühren etwa 8 Minuten braten, bis er zusammenfällt und an Volumen verliert. Passierte Tomaten und Gewürze einrühren, die Hitze reduzieren und 10 Minuten köcheln, bis der Kohl weich und glänzend ist. Nach Geschmack salzen und warm servieren, als Hauptgericht oder herzhafte Beilage.',
      pt:'Corte o repolho em tiras finas e a cebola em rodelas. Aqueça o óleo numa frigideira larga e refogue a cebola e o alho 4 minutos, até ficarem macios. Junte o repolho e cozinhe em lume médio, mexendo com frequência, cerca de 8 minutos até murchar e reduzir. Junte o tomate passata e as especiarias, baixe o lume e cozinhe 10 minutos, até o repolho ficar macio e brilhante. Tempere com sal a gosto e sirva quente, como prato principal ou acompanhamento substancial.',
      ru:'Тонко нашинкуйте капусту и нарежьте лук тонкими ломтиками. Разогрейте масло в широкой сковороде и обжарьте лук и чеснок 4 минуты, до мягкости. Добавьте капусту и готовьте на среднем огне, часто помешивая, около 8 минут, пока она не осядет и не уменьшится в объёме. Вмешайте протёртые томаты и специи, убавьте огонь и тушите 10 минут, пока капуста не станет мягкой и глянцевой. Посолите по вкусу и подавайте тёплой, как основное блюдо или сытный гарнир.',
      ar:'قطّع الملفوف شرائح رفيعة والبصل شرائح. سخّن الزيت في مقلاة واسعة وشوّح البصل والثوم 4 دقائق حتى يلين. أضف الملفوف واطهه على نار متوسطة مع التقليب المتكرر نحو 8 دقائق حتى يذبل ويقلّ حجمه. أضف الطماطم المهروسة والبهارات، اخفض النار واطهه 10 دقائق حتى ينضج الملفوف ويلمع. تبّل بالملح حسب الذوق وقدّمه دافئاً كطبق رئيسي أو جانبي دسم.',
      zh:'卷心菜切细丝，洋葱切片。宽口锅热油，下洋葱和蒜炒4分钟至变软。加入卷心菜，中火不时翻炒约8分钟，至变软、体积缩小。加入番茄泥和香料，转小火煮10分钟，至卷心菜软烂、油亮。按口味加盐，趁热作为主菜或丰盛配菜上桌。',
      ja:'キャベツは細切り、玉ねぎは薄切りにする。広めのフライパンに油を温め、玉ねぎとにんにくを4分、柔らかくなるまで炒める。キャベツを加え、中火でよく混ぜながら約8分、かさが減ってしんなりするまで炒める。トマトピューレとスパイスを加え、弱火にして10分、キャベツが柔らかくつやが出るまで煮る。塩で好みに調え、主菜または食べ応えのある副菜として温かいうちに供する。',
      hi:'पत्ता गोभी को बारीक काटें और प्याज़ को पतला स्लाइस करें। चौड़े पैन में तेल गरम करें और प्याज़ व लहसुन 4 मिनट नरम होने तक भूनें। गोभी डालें और मध्यम आँच पर बार-बार चलाते हुए लगभग 8 मिनट पकाएँ जब तक मुरझाकर मात्रा कम हो जाए। टमाटर प्यूरी और मसाले डालें, आँच धीमी करें और 10 मिनट पकाएँ जब तक गोभी नरम और चमकदार हो। स्वादानुसार नमक डालें और गरम, मुख्य व्यंजन या भरपूर साइड के रूप में परोसें।',
      tr:'Lahanayı ince ince doğrayın, soğanı ince dilimleyin. Geniş bir tavada yağı ısıtın ve soğan ile sarımsağı 4 dakika, yumuşayana dek kavurun. Lahanayı ekleyip orta ateşte sık karıştırarak yaklaşık 8 dakika, sölpüyüp hacmi azalana dek pişirin. Domates püresi ve baharatı ekleyin, ateşi kısıp 10 dakika, lahana yumuşayıp parlayana dek pişirin. Damak tadınıza göre tuzlayın ve ana yemek ya da doyurucu garnitür olarak sıcak servis edin.',
      it:'Affetta finemente il cavolo e taglia la cipolla a fettine sottili. Scalda l’olio in una padella ampia e fai appassire cipolla e aglio per 4 minuti, finché sono morbidi. Aggiungi il cavolo e cuoci a fuoco medio, mescolando spesso, per circa 8 minuti finché appassisce e si riduce. Unisci la passata e le spezie, abbassa la fiamma e fai sobbollire 10 minuti, finché il cavolo è tenero e lucido. Regola di sale a piacere e servi caldo, come piatto principale o contorno sostanzioso.',
      ko:'양배추는 곱게 채 썰고 양파는 얇게 슬라이스한다. 넓은 팬에 기름을 데우고 양파와 마늘을 4분간 부드러워질 때까지 볶는다. 양배추를 넣고 중불에서 자주 저으며 약 8분간 숨이 죽고 부피가 줄 때까지 볶는다. 토마토 퓌레와 향신료를 넣고 불을 줄여 10분간 양배추가 부드럽고 윤기가 돌 때까지 끓인다. 기호대로 소금 간을 하고, 메인이나 든든한 곁들임으로 따뜻하게 낸다.' } },

  { id:'budget_009', name:NAMES.ricePud, o:O.INT, servings:2, prep:5, cook:30, costRon:4, nut:{cal:400,prot:12,carb:68,fat:9,fib:1}, tags:['budget','vegetarian','family'],
    ing:[ {q:120,u:'g',n:I.rice}, {q:700,u:'ml',n:I.milk}, {q:60,u:'g',n:I.sugar}, {n:I.salt} ],
    steps:{
      ro:'Clătește orezul scurt, apoi pune-l într-o oală cu laptele și un praf mic de sare. Adu la un clocot blând la foc mic și fierbe, amestecând des ca să nu se prindă de fund, circa 25 de minute, până orezul e moale, iar amestecul gros și cremos. Adaugă zahărul și mai fierbe 3 minute, ca să se dizolve. Ține minte că se îngroașă și mai mult pe măsură ce se răcește, așa că ia-l de pe foc cât e încă puțin lejer. Servește cald sau lasă-l la rece și presară scorțișoară dacă îți place.',
      en:'Rinse the rice briefly, then put it in a pot with the milk and a small pinch of salt. Bring it to a gentle simmer over low heat and cook, stirring often so it doesn’t catch on the bottom, for about 25 minutes until the rice is soft and the mixture is thick and creamy. Stir in the sugar and cook for 3 more minutes to dissolve it. Remember it thickens further as it cools, so take it off the heat while still a little loose. Serve warm, or chill it and dust with cinnamon if you like.',
      es:'Enjuaga el arroz brevemente y ponlo en una olla con la leche y una pizca pequeña de sal. Lleva a fuego suave y cocina, removiendo a menudo para que no se pegue, unos 25 minutos hasta que el arroz esté blando y la mezcla espesa y cremosa. Añade el azúcar y cocina 3 minutos más para que se disuelva. Recuerda que espesa más al enfriar, así que retíralo del fuego cuando aún esté algo suelto. Sirve caliente, o enfríalo y espolvorea canela si te gusta.',
      fr:'Rincez brièvement le riz, puis mettez-le dans une casserole avec le lait et une petite pincée de sel. Portez à frémissement à feu doux et faites cuire, en remuant souvent pour que ça n’attache pas, environ 25 minutes jusqu’à ce que le riz soit tendre et le mélange épais et crémeux. Ajoutez le sucre et prolongez la cuisson 3 minutes pour le dissoudre. Rappelez-vous que ça épaissit encore en refroidissant : retirez du feu tant que c’est encore un peu coulant. Servez chaud, ou froid avec une pincée de cannelle si vous aimez.',
      de:'Den Reis kurz abspülen, dann mit der Milch und einer kleinen Prise Salz in einen Topf geben. Bei niedriger Hitze sanft zum Köcheln bringen und etwa 25 Minuten kochen, dabei oft rühren, damit nichts ansetzt, bis der Reis weich und die Masse dick und cremig ist. Den Zucker einrühren und weitere 3 Minuten kochen, bis er sich löst. Denk daran, dass es beim Abkühlen noch dicker wird — nimm es vom Herd, solange es noch etwas locker ist. Warm servieren oder kalt stellen und nach Belieben mit Zimt bestäuben.',
      pt:'Lave o arroz rapidamente e coloque-o numa panela com o leite e uma pequena pitada de sal. Leve a lume brando e cozinhe, mexendo com frequência para não pegar, cerca de 25 minutos até o arroz ficar macio e a mistura espessa e cremosa. Junte o açúcar e cozinhe mais 3 minutos para dissolver. Lembre-se de que engrossa mais ao arrefecer, por isso retire do lume enquanto ainda está um pouco solto. Sirva quente, ou refrigere e polvilhe com canela a gosto.',
      ru:'Быстро промойте рис и положите в кастрюлю с молоком и небольшой щепоткой соли. Доведите до лёгкого кипения на слабом огне и варите, часто помешивая, чтобы не пригорело, около 25 минут, пока рис не станет мягким, а масса — густой и кремовой. Вмешайте сахар и варите ещё 3 минуты до растворения. Помните, что при остывании масса густеет ещё сильнее, поэтому снимайте с огня, пока она чуть жидковата. Подавайте тёплым или охладите и посыпьте корицей по желанию.',
      ar:'اغسل الأرز سريعاً ثم ضعه في قدر مع الحليب ورشة ملح صغيرة. اجعله يغلي بلطف على نار هادئة واطهه مع التحريك المتكرر كي لا يلتصق، نحو 25 دقيقة حتى يلين الأرز ويصبح الخليط ثخيناً وكريمياً. أضف السكر واطهه 3 دقائق إضافية ليذوب. تذكّر أنه يثخن أكثر عند البرودة، لذا ارفعه عن النار وهو لا يزال طرياً بعض الشيء. قدّمه دافئاً، أو برّده ورشّ القرفة إن أحببت.',
      zh:'米略微冲洗，放入锅中，加牛奶和一小撮盐。小火轻煮，常搅拌以防粘底，约25分钟至米软、质地浓稠绵滑。加入糖再煮3分钟至溶化。记住放凉后会更稠，所以在还略稀时就离火。温热食用，或冷藏后按喜好撒些肉桂粉。',
      ja:'米をさっと洗い、鍋に牛乳と塩少々とともに入れる。弱火で静かに煮立て、焦げ付かないようによくかき混ぜながら約25分、米が柔らかくなり全体がとろりと濃厚になるまで煮る。砂糖を加えてさらに3分、溶けるまで煮る。冷めるとさらに固くなるので、まだ少しゆるいうちに火から下ろす。温かいまま、または冷やして好みでシナモンをふって供する。',
      hi:'चावल को झटपट धोएँ, फिर बर्तन में दूध और छोटी चुटकी नमक के साथ डालें। धीमी आँच पर हल्का उबाल लाएँ और तले में न लगे इसलिए बार-बार चलाते हुए लगभग 25 मिनट पकाएँ जब तक चावल नरम और मिश्रण गाढ़ा-मलाईदार न हो। चीनी मिलाएँ और 3 मिनट और पकाएँ ताकि घुल जाए। याद रखें ठंडा होने पर यह और गाढ़ा होता है, इसलिए थोड़ा पतला रहते ही आँच से उतार लें। गरम परोसें, या ठंडा कर पसंद हो तो दालचीनी छिड़कें।',
      tr:'Pirinci kısaca yıkayıp süt ve küçük bir tutam tuzla tencereye alın. Kısık ateşte hafifçe kaynatın ve dibe tutmasın diye sık karıştırarak yaklaşık 25 dakika, pirinç yumuşayıp karışım koyulaşıp kremamsı olana dek pişirin. Şekeri ekleyip erimesi için 3 dakika daha pişirin. Soğudukça daha da koyulaşacağını unutmayın; hâlâ biraz akışkanken ocaktan alın. Sıcak servis edin ya da soğutup isterseniz tarçın serpin.',
      it:'Sciacqua velocemente il riso, poi mettilo in una pentola con il latte e un piccolo pizzico di sale. Porta a leggero sobbollire a fuoco basso e cuoci, mescolando spesso perché non attacchi, per circa 25 minuti finché il riso è morbido e il composto denso e cremoso. Unisci lo zucchero e cuoci altri 3 minuti per scioglierlo. Ricorda che si addensa ancora raffreddandosi, quindi togli dal fuoco quando è ancora un po’ morbido. Servi caldo, oppure freddo con una spolverata di cannella se ti piace.',
      ko:'쌀을 가볍게 헹군 뒤 냄비에 우유, 소금 아주 조금과 함께 넣는다. 약불에서 은근히 끓기 시작하면 바닥에 눌어붙지 않게 자주 저으며 약 25분간 쌀이 부드럽고 전체가 되직하고 크리미해질 때까지 끓인다. 설탕을 넣고 3분 더 끓여 녹인다. 식으면 더 되직해지니 조금 묽을 때 불에서 내린다. 따뜻하게 내거나 차게 식혀 원하면 계핏가루를 뿌린다.' } },

  { id:'budget_010', name:NAMES.polenta, o:O.RO, servings:2, prep:2, cook:25, costRon:2, nut:{cal:340,prot:7,carb:68,fat:3,fib:6}, tags:['budget','vegan','one-pot'],
    ing:[ {q:150,u:'g',n:I.cornmeal}, {q:750,u:'ml',n:I.water}, {n:I.salt} ],
    steps:{
      ro:'Adu apa la fiert într-o oală cu fund gros și adaugă un praf bun de sare. Toarnă mălaiul în ploaie subțire, amestecând continuu cu telul — ăsta e secretul ca să nu se formeze cocoloașe. Redu focul și fierbe, amestecând des cu o lingură de lemn, circa 20 de minute, până se îngroașă, devine netedă și se desprinde de pereții oalei. Dacă se întărește prea tare, bate în ea un strop de apă fierbinte. Servește fierbinte, ca garnitură, simplă sau sub o tocană.',
      en:'Bring the water to a boil in a heavy pot and add a good pinch of salt. Pour in the cornmeal in a slow, steady stream while whisking constantly — this is the key to avoiding lumps. Lower the heat and cook, stirring often with a wooden spoon, for about 20 minutes, until it is thick, smooth, and pulls away from the sides of the pot. If it gets too stiff, beat in a splash of hot water. Serve hot as a side, on its own, or under a stew.',
      es:'Lleva el agua a ebullición en una olla de fondo grueso y añade una buena pizca de sal. Vierte la harina de maíz en un hilo lento y constante sin dejar de batir — esta es la clave para evitar grumos. Baja el fuego y cocina, removiendo a menudo con cuchara de madera, unos 20 minutos, hasta que espese, quede suave y se despegue de las paredes. Si se pone muy dura, incorpora un chorrito de agua caliente. Sirve caliente como guarnición, sola o bajo un guiso.',
      fr:'Portez l’eau à ébullition dans une casserole à fond épais et ajoutez une bonne pincée de sel. Versez la semoule de maïs en un filet lent et régulier en fouettant sans cesse — c’est la clé pour éviter les grumeaux. Baissez le feu et faites cuire, en remuant souvent à la cuillère en bois, environ 20 minutes, jusqu’à ce que ce soit épais, lisse et que ça se détache des parois. Si c’est trop ferme, incorporez un peu d’eau chaude. Servez chaud en accompagnement, seul ou sous un ragoût.',
      de:'Das Wasser in einem schweren Topf zum Kochen bringen und eine gute Prise Salz zugeben. Den Maisgrieß in einem langsamen, gleichmäßigen Strahl einrieseln lassen und dabei ständig rühren — das ist der Schlüssel gegen Klümpchen. Die Hitze reduzieren und etwa 20 Minuten kochen, dabei oft mit einem Holzlöffel rühren, bis es dick, glatt ist und sich vom Topfrand löst. Wird es zu fest, einen Schuss heißes Wasser einrühren. Heiß als Beilage servieren, pur oder unter einem Eintopf.',
      pt:'Leve a água a ferver numa panela de fundo grosso e junte uma boa pitada de sal. Deite o fubá em fio lento e constante, mexendo sem parar — este é o segredo para evitar grumos. Baixe o lume e cozinhe, mexendo com frequência com colher de pau, cerca de 20 minutos, até engrossar, ficar liso e descolar das paredes. Se ficar muito rijo, envolva um pouco de água quente. Sirva quente como acompanhamento, simples ou sob um guisado.',
      ru:'Вскипятите воду в толстостенной кастрюле и добавьте хорошую щепотку соли. Всыпайте кукурузную крупу медленной ровной струйкой, постоянно взбивая венчиком — это главный секрет против комков. Убавьте огонь и варите, часто помешивая деревянной ложкой, около 20 минут, пока масса не станет густой, гладкой и не начнёт отставать от стенок. Если станет слишком плотной, вбейте немного горячей воды. Подавайте горячей как гарнир, саму по себе или под рагу.',
      ar:'اغلِ الماء في قدر سميك القاع وأضف رشة ملح جيدة. أضف دقيق الذرة في خيط بطيء ومنتظم مع الخفق المستمر — هذا هو سرّ تجنّب التكتّل. اخفض النار واطهه مع التحريك المتكرر بملعقة خشب نحو 20 دقيقة حتى يثخن ويصبح ناعماً وينفصل عن جدران القدر. إن صار قاسياً جداً، اخفق فيه رشة ماء ساخن. قدّمه ساخناً كطبق جانبي، وحده أو تحت يخنة.',
      zh:'厚底锅将水烧开，加一大撮盐。玉米粉呈细流状缓慢均匀倒入，同时不停搅打——这是不结块的关键。转小火，用木勺常搅约20分钟，至浓稠顺滑、能脱离锅壁。太硬就打入少许热水。趁热作为配菜食用，可单吃或垫在炖菜下。',
      ja:'厚手の鍋で水を沸かし、塩をしっかりひとつまみ加える。コーンミールを細くゆっくり一定に流し入れながら、絶えず泡立て器で混ぜる——これがだまを防ぐ鍵。弱火にして木べらでよく混ぜながら約20分、とろりと滑らかになり鍋肌から離れるまで煮る。固くなりすぎたら熱湯を少し加えて混ぜる。付け合わせとして、そのまま、または煮込みの下に敷いて熱いうちに供する。',
      hi:'मोटे तले वाले बर्तन में पानी उबालें और एक अच्छी चुटकी नमक डालें। मक्के के आटे को धीमी, एकसमान धार में डालते हुए लगातार फेंटें — गुठलियाँ न बनने का यही राज़ है। आँच धीमी करें और लकड़ी के चम्मच से बार-बार चलाते हुए लगभग 20 मिनट पकाएँ, जब तक गाढ़ा, चिकना हो और बर्तन की दीवारों से छूटने लगे। बहुत सख्त हो जाए तो थोड़ा गरम पानी फेंटकर मिलाएँ। गरमागरम साइड डिश के रूप में, अकेले या किसी करी के नीचे परोसें।',
      tr:'Kalın tabanlı bir tencerede suyu kaynatın ve iyi bir tutam tuz ekleyin. Mısır ununu yavaş ve düzenli bir şekilde dökerken sürekli çırpın — topaklanmayı önlemenin anahtarı budur. Ateşi kısın ve tahta kaşıkla sık karıştırarak yaklaşık 20 dakika, koyulaşıp pürüzsüzleşene ve tencere kenarından ayrılana dek pişirin. Fazla katılaşırsa biraz sıcak su çırparak ekleyin. Garnitür olarak, tek başına ya da bir yahninin altında sıcak servis edin.',
      it:'Porta a bollore l’acqua in una pentola dal fondo spesso e aggiungi una buona presa di sale. Versa la farina di mais a pioggia lenta e costante frustando di continuo — è il segreto per evitare i grumi. Abbassa la fiamma e cuoci, mescolando spesso con un cucchiaio di legno, per circa 20 minuti, finché è densa, liscia e si stacca dalle pareti. Se diventa troppo soda, incorpora un goccio d’acqua calda. Servi calda come contorno, da sola o sotto uno spezzatino.',
      ko:'두꺼운 냄비에 물을 끓이고 소금을 넉넉히 한 꼬집 넣는다. 옥수수가루를 천천히 일정하게 흘려 넣으며 거품기로 계속 저어준다 — 덩어리를 막는 핵심이다. 불을 줄이고 나무 주걱으로 자주 저으며 약 20분간 되직하고 매끈해져 냄비 벽에서 떨어질 때까지 끓인다. 너무 단단해지면 뜨거운 물을 조금 넣어 저어 푼다. 곁들임으로, 그대로 또는 스튜 아래에 깔아 뜨겁게 낸다.' } },
];

const recipes = SPECS.map(mk);

export { recipes };
export default recipes;
export const BUDGET_RECIPES = recipes;

if (typeof window !== 'undefined') {
  window.BUDGET_RECIPES = recipes;
}
